-- Виктор в Telegram (2026-09-07): в попапе локации информации должно быть
-- больше, чем сейчас (было по одной строке), но без «длинных» простыней —
-- расширил описания всех локаций до 2-4 коротких предложений: что именно
-- увидим, чем место примечательно и практические детали (оплата по факту,
-- подъезжаем на машине и т.п.). В списке маршрута описание всё так же
-- обрезается до одной строки (line-clamp-1), полный текст виден в попапе.
--
-- Обновляем ТОЛЬКО description.ru у каждой локации через jsonb_set —
-- фото, article_slug и порядок локаций не трогаем (иначе пришлось бы
-- переписывать весь itinerary целиком и был бы риск затереть уже
-- накаченные правки, например реордер фото Хон Чонга).

with new_desc(title, descr) as (values
  ('Капибары и вьетнамский кофе'::text, 'Начинаем день в кафе с капибарами — их можно погладить и покормить, они спокойные и не боятся людей. Параллельно завариваем кофе через традиционный вьетнамский фильтр фин: медленно, как это делают местные.'),
  ('Башня Куанг-Минь', 'Новая золотая 13-ярусная башня на горе Фыонг Хоанг — одна из самых заметных точек Нячанга. Сверху открывается панорама на весь город, бухту, острова и линию побережья. Подъезжаем на автомобиле, долго идти пешком не нужно.'),
  ('Пагода Лонгшон', 'Главный буддийский храм Нячанга: белая статуя сидящего Будды высотой 24 метра видна из разных точек города. Внутри комплекса — лежащий Будда, действующий храм и монастырь. К верхней части подъезжаем на машине, минуя 152 ступени под солнцем.'),
  ('Кафедральный собор Христа-Царя', 'Каменный неоготический собор французской колониальной эпохи, построен в 1930-х из грубого серого камня. Витражи, высокая колокольня с часами и совсем не тропическая атмосфера внутри — контраст с остальным маршрутом.'),
  ('Башни По Нагар', 'Действующий храмовый комплекс древнего Чамского королевства, VII–XIII века — старше большинства построек Вьетнама. Красный кирпич без раствора, резьба по камню и вид на реку Кай. Сюда до сих пор приходят молиться местные.'),
  ('Хон Чонг', 'Гранитный мыс с нагромождением валунов, отполированных морем. С камней — лучшая панорама залива, острова Хон Че и гор на материке. Рядом культурный павильон, где иногда играют на традиционных инструментах.'),
  ('Музей Александра Йерсена', 'Дом-музей учёного, который открыл возбудителя чумы и основал в Нячанге Институт Пастера. Личные вещи, приборы, библиотека и фотографии — короткая, но живая история города с европейской стороны. Йерсена во Вьетнаме до сих пор почитают.'),
  ('Обед в кафе с вертолётом', 'Обед в необычном кафе: во дворе стоит настоящий вертолёт, есть пруд с карпами кои и игуаны. Блюда каждый выбирает под себя — заказ оплачивается по факту, не входит в стоимость тура.'),
  ('Tiệm Cafe Đồng Lúa', 'Завтрак в кафе, построенном прямо среди рабочих рисовых полей — деревянные веранды и мостки посреди зелени. Рядом пруд с лотосами. Спокойная точка старта перед дорогой к морю.'),
  ('Католический собор Ванзя', 'Неоготический собор с двумя колокольнями — заметен с трассы за несколько километров. Крупная местная католическая община, служба на вьетнамском. Внутри высокие своды и витражи, совсем другая сторона Центрального Вьетнама.'),
  ('Вид на остров Хон Нуа', 'Смотровая остановка по дороге: открытое море, силуэт острова Хон Нуа и горный берег. Короткая пауза размять ноги и сделать кадр.'),
  ('Маяк Дай Лань', 'Один из старейших действующих маяков Вьетнама, первая башня — 1890 год, французская постройка. Мыс считается одной из самых восточных точек материковой страны. С него видно сразу и бухту с лодками, и открытое море.'),
  ('Дикий пляж Бай Мон', 'Бухта у подножия мыса с маяком: светлый песок, чистая вода, скалы по краям — и ни одного шезлонга, бара или отеля. Мыс закрывает пляж от волн, вода обычно спокойнее, чем на соседних участках.'),
  ('Обед в Hương Biển Vũng Rô', 'Бухта Вунг Ро — защищённая горами гавань с плавучими фермами, где разводят рыбу и лобстеров. Ресторан стоит на берегу, морепродукты берут из этой же воды в тот же день. Выбираете по улову, оплата по факту.'),
  ('Буддийский храм', 'Небольшой действующий храм на обратной дороге — без туристических автобусов. Внутри золотая статуя Будды и подношения от местной общины, снаружи ухоженный двор с пагодой. Тихая точка, чтобы выдохнуть после дня в дороге.')
)
update tours t set itinerary = (
  select jsonb_agg(
    case when nd.descr is not null
      then jsonb_set(e.loc, '{description,ru}', to_jsonb(nd.descr))
      else e.loc
    end
    order by e.ord
  )
  from jsonb_array_elements(t.itinerary) with ordinality as e(loc, ord)
  left join new_desc nd on nd.title = e.loc->'title'->>'ru'
)
where t.slug in ('nyachang-avtorskiy', 'mayak-dai-lan');
